1	//! `McpTool` — adapts a remote MCP tool to core's `Tool<Ctx>` trait.
2	
3	use std::marker::PhantomData;
4	use std::sync::LazyLock;
5	
6	use async_trait::async_trait;
7	use paigasus_helikon_core::{Tool, ToolContext, ToolEffect, ToolError, ToolOutput};
8	use rmcp::model::CallToolResult;
9	
10	use crate::client::handle::McpServerHandle;
