12	/// Map an MCP `CallToolResult` into core's `ToolOutput`/`ToolError`.
13	///
14	/// - `is_error == Some(true)` → `ToolError::Other` carrying the text content.
15	/// - `structured_content` (when present) becomes `ToolOutput.content` as-is.
16	/// - Otherwise a single text content becomes a JSON string; anything else is
17	///   serialized as a JSON array of content blocks.
18	pub(crate) fn map_call_result(result: CallToolResult) -> Result<ToolOutput, ToolError> {
19	    if result.is_error == Some(true) {
20	        // Known gap: a structured_error result also carries
21	        // structured_content; today only the text rendering reaches the
22	        // model. Surface the structured value if a real server needs it
23	        // (file a follow-up ticket when one does).
24	        let msg = content_text(&result.content);
25	        return Err(ToolError::Other(anyhow::anyhow!(
26	            "MCP tool returned an error: {msg}"
27	        )));
28	    }
29	    if let Some(v) = result.structured_content {
30	        return Ok(ToolOutput::new(v));
31	    }
32	    let content = result.content;
33	    if content.len() == 1 && content[0].as_text().is_some() {
34	        let text = content.into_iter().next().unwrap();
35	        // SAFETY: guarded by `as_text().is_some()` above.
36	        let rmcp::model::RawContent::Text(t) = text.raw else {
37	            unreachable!()
38	        };
39	        return Ok(ToolOutput::new(serde_json::Value::String(t.text)));
40	    }
41	    let arr =
42	        serde_json::to_value(&content).map_err(|e| ToolError::Other(anyhow::Error::from(e)))?;
43	    Ok(ToolOutput::new(arr))
44	}
45	
46	/// Concatenate the text parts of a content vec for error messages.
47	fn content_text(content: &[rmcp::model::Content]) -> String {
48	    let parts: Vec<&str> = content
49	        .iter()
50	        .filter_map(|c| c.as_text().map(|t| t.text.as_str()))
51	        .collect();
52	    if parts.is_empty() {
53	        "<no text content>".to_owned()
54	    } else {
55	        parts.join("\n")
56	    }
57	}
