59	/// Placeholder schema advertised by lazy-mode tools.
60	static PLACEHOLDER_SCHEMA: LazyLock<serde_json::Value> =
61	    LazyLock::new(|| serde_json::json!({ "type": "object", "additionalProperties": true }));
62	
63	/// A remote MCP tool adapted to core's [`Tool`].
64	///
65	/// `Ctx` is a phantom: MCP tools never read the user context, so one handle
66	/// serves agents of any context type. `ToolEffect::Write` is never produced —
67	/// server-declared annotations are untrusted metadata and must not unlock
68	/// `AcceptEdits` auto-approval; `read_only_hint == true` maps to `ReadOnly`,
69	/// everything else to `SideEffect`.
70	pub struct McpTool<Ctx> {
71	    handle: McpServerHandle,
72	    wire_name: String,
73	    name: String,
74	    description: String,
75	    schema: serde_json::Value,
76	    output_schema: Option<serde_json::Value>,
77	    effect: ToolEffect,
78	    _ctx: PhantomData<fn() -> Ctx>,
79	}
80	
81	impl<Ctx> McpTool<Ctx> {
82	    pub(crate) fn new(handle: McpServerHandle, tool: &rmcp::model::Tool, lazy: bool) -> Self {
83	        let wire_name = tool.name.to_string();
84	        let name = handle.prefixed(&wire_name);
85	        let mut description = tool.description.as_deref().unwrap_or_default().to_owned();
86	        let schema = if lazy {
87	            let hint = format!(
88	                "(Full input schema available via the `{}` tool.)",
89	                handle.prefixed("search_tools")
90	            );
91	            if !description.is_empty() {
92	                description.push(' ');
93	            }
94	            description.push_str(&hint);
95	            PLACEHOLDER_SCHEMA.clone()
96	        } else {
97	            serde_json::Value::Object((*tool.input_schema).clone())
98	        };
99	        let output_schema = if lazy {
100	            None
101	        } else {
102	            tool.output_schema
103	                .as_ref()
104	                .map(|s| serde_json::Value::Object((**s).clone()))
105	        };
106	        let effect = match &tool.annotations {
107	            Some(a) if a.read_only_hint == Some(true) => ToolEffect::ReadOnly,
108	            _ => ToolEffect::SideEffect,
109	        };
110	        Self {
111	            handle,
112	            wire_name,
113	            name,
114	            description,
115	            schema,
116	            output_schema,
117	            effect,
118	            _ctx: PhantomData,
119	        }
120	    }
121	}
