123	#[async_trait]
124	impl<Ctx> Tool<Ctx> for McpTool<Ctx>
125	where
126	    Ctx: Send + Sync + 'static,
127	{
128	    fn name(&self) -> &str {
129	        &self.name
130	    }
131	
132	    fn description(&self) -> &str {
133	        &self.description
134	    }
135	
136	    fn schema(&self) -> &serde_json::Value {
137	        &self.schema
138	    }
139	
140	    fn output_schema(&self) -> Option<&serde_json::Value> {
141	        self.output_schema.as_ref()
142	    }
143	
144	    fn effect(&self) -> ToolEffect {
145	        self.effect
146	    }
147	
148	    async fn invoke(
149	        &self,
150	        ctx: &ToolContext<Ctx>,
151	        args: serde_json::Value,
152	    ) -> Result<ToolOutput, ToolError> {
153	        let arguments = match args {
154	            serde_json::Value::Object(map) => Some(map),
155	            serde_json::Value::Null => None,
156	            other => {
157	                return Err(ToolError::InvalidArgs {
158	                    schema_errors: vec![format!(
159	                        "MCP tools take a JSON object as arguments, got: {other}"
160	                    )],
161	                })
162	            }
163	        };
164	        // Race the remote call against the run's cancellation token: rmcp's
165	        // `call_tool` waits indefinitely, so a hung MCP server must not hang
166	        // the whole agent run past a cancel.
167	        let cancel = ctx.cancel().clone();
168	        let call = self.handle.call_tool_raw(&self.wire_name, arguments);
169	        let result = tokio::select! {
170	            biased;
171	            _ = cancel.cancelled() => {
172	                return Err(ToolError::Other(anyhow::anyhow!(
173	                    "MCP tool call `{}` cancelled",
174	                    self.name
175	                )));
176	            }
177	            r = call => r,
178	        };
179	        let result = result.map_err(|e| ToolError::Other(anyhow::Error::from(e)))?;
180	        map_call_result(result)
181	    }
182	}
