186	    use super::*;
187	    use rmcp::model::{CallToolResult, Content};
188	
189	    #[test]
190	    fn structured_content_wins() {
191	        let r = CallToolResult::structured(serde_json::json!({"a": 1}));
192	        let out = map_call_result(r).unwrap();
193	        assert_eq!(out.content, serde_json::json!({"a": 1}));
194	    }
195	
196	    #[test]
197	    fn single_text_becomes_string() {
198	        let r = CallToolResult::success(vec![Content::text("hello")]);
199	        let out = map_call_result(r).unwrap();
200	        assert_eq!(out.content, serde_json::json!("hello"));
201	    }
202	
203	    #[test]
204	    fn multi_content_becomes_array() {
205	        let r = CallToolResult::success(vec![Content::text("a"), Content::text("b")]);
206	        let out = map_call_result(r).unwrap();
207	        assert!(out.content.is_array());
208	        assert_eq!(out.content.as_array().unwrap().len(), 2);
209	        let arr = out.content.as_array().unwrap();
210	        assert_eq!(arr[0]["type"], "text");
211	        assert_eq!(arr[0]["text"], "a");
212	        assert_eq!(arr[1]["text"], "b");
213	    }
214	
215	    #[test]
216	    fn is_error_maps_to_tool_error() {
217	        let r = CallToolResult::error(vec![Content::text("kaboom")]);
218	        let err = map_call_result(r).unwrap_err();
219	        assert!(err.to_string().contains("kaboom"));
220	    }
221	}
